import 'package:flutter/material.dart';
import '../../core/api.dart';
class DashboardPage extends StatefulWidget{const DashboardPage({super.key});@override State<DashboardPage> createState()=>_DashboardPageState();}
class _DashboardPageState extends State<DashboardPage>{Map<String,dynamic>? d;String? e;@override void initState(){super.initState();load();}Future<void> load()async{try{d=await Api.instance.get('/reports/dashboard/');}catch(x){e=x.toString();}if(mounted)setState((){});}Widget card(String title,String value,IconData icon)=>Card(child:Padding(padding:const EdgeInsets.all(18),child:Row(children:[Icon(icon,size:34),const SizedBox(width:14),Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title),Text(value,style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold))])])));@override Widget build(BuildContext c){if(e!=null)return Center(child:Text('Dashboard unavailable\n$e',textAlign:TextAlign.center));if(d==null)return const Center(child:CircularProgressIndicator());return RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[card('Sales', '₦${d!['sales_total']}',Icons.trending_up),card('Transactions','${d!['sales_count']}',Icons.receipt),card('Products','${d!['products']}',Icons.inventory),card('Customers','${d!['customers']}',Icons.people),card('Expenses','₦${d!['expenses_total']}',Icons.money_off)]));}}
